def HasBoundedRightApproximation (P : Submodule 𝕜 B) (M : ℝ) : Prop :=
  ∀ (s : Finset P) (ε : ℝ), 0 < ε →
    ∃ e ∈ P, ‖e‖ ≤ M ∧ ∀ z ∈ s, ‖z.val - z.val * e‖ ≤ ε

